    for i, page in enumerate(reader.pages):
        print(f"--- Page {i+1} ---")
        print(page.extract_text())

def read_docx(p):
    print("="*80)
    print("DOCX:", p)
    doc = docx.Document(p)
    for para in doc.paragraphs:
        if para.text.strip():
