base = "/filesystem/final_batch4__structural_task7_roof_deck_design__blind"

def read_pdf(p):
    print("="*80)
    print("PDF:", p)
    out = subprocess.check_output(["pdftotext", "-layout", p, "-"]).decode("utf-8", errors="replace")
